    fun `mediaOffer`(`peer`: kotlin.String, `kind`: TandemMediaKind, `facing`: TandemMediaFacing, `extend`: kotlin.Boolean)
    
    fun `mediaPolicy`(`id`: kotlin.String): TandemMediaPolicy
    
