    fun `mediaSendInput`(`session`: kotlin.ULong, `input`: TandemMediaInput)
    
    fun `mediaSessions`(): List<TandemMediaSession>
    
    fun `mediaStats`(`session`: kotlin.ULong): TandemMediaStats?
    
    /**
