     */
    fun `mediaUpdate`(`session`: kotlin.ULong, `update`: TandemMediaUpdate)
    
    fun `name`(): kotlin.String
    
    /**
     * Call when Wi-Fi, mobile data or the VPN changed.
     */
    fun `networkChanged`()
    
    suspend fun `notificationAction`(`target`: kotlin.String, `key`: kotlin.String, `button`: kotlin.String, `reply`: kotlin.String?, `dismiss`: kotlin.Boolean)
    
    /**
     * Asks a device to open a page of its settings, one it named in its features.
     */
    suspend fun `openSettingsOn`(`target`: kotlin.String, `page`: kotlin.String)
    
    /**
