    fun `sendScroll`(`id`: kotlin.String, `dx`: kotlin.Short, `dy`: kotlin.Short)
    
    suspend fun `sendText`(`targets`: List<kotlin.String>, `text`: kotlin.String, `isUrl`: kotlin.Boolean, `open`: kotlin.Boolean): List<kotlin.String>
    
    /**
     * Asks for a password, or answers such a question, over the network or over a Bluetooth link.
     */
    suspend fun `sendWifi`(`target`: kotlin.String, `wifi`: TandemWifi)
    
    /**
