    fun `setCameraStream`(`port`: kotlin.UShort)
    
    fun `setDeviceSettings`(`id`: kotlin.String, `clipboard`: kotlin.Boolean, `autoAccept`: kotlin.Boolean, `notifications`: kotlin.Boolean)
    
    /**
