    override fun write(value: TandemWifiNetwork, buf: ByteBuffer) {
            FfiConverterString.write(value.`ssid`, buf)
            FfiConverterTypeTandemWifiSecurity.write(value.`security`, buf)
            FfiConverterBoolean.write(value.`hidden`, buf)
            FfiConverterBoolean.write(value.`locked`, buf)
    }
}



sealed class TandemCallAction {
    
    object Answer : TandemCallAction()
    
    
    object Reject : TandemCallAction()
    
    
    object Silence : TandemCallAction()
    
    
    object Hangup : TandemCallAction()
    
    
    data class RejectWithMessage(
        val `message`: kotlin.String) : TandemCallAction()
        
    {
        

        companion object
    }
    
    object MoveToThisDevice : TandemCallAction()
    
    
    object MoveBack : TandemCallAction()
    
    
    object MuteMic : TandemCallAction()
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeTandemCallAction : FfiConverterRustBuffer<TandemCallAction>{
    override fun read(buf: ByteBuffer): TandemCallAction {
        return when(buf.getInt()) {
            1 -> TandemCallAction.Answer
            2 -> TandemCallAction.Reject
            3 -> TandemCallAction.Silence
            4 -> TandemCallAction.Hangup
            5 -> TandemCallAction.RejectWithMessage(
                FfiConverterString.read(buf),
                )
            6 -> TandemCallAction.MoveToThisDevice
            7 -> TandemCallAction.MoveBack
            8 -> TandemCallAction.MuteMic
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TandemCallAction): ULong = when(value) {
        is TandemCallAction.Answer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TandemCallAction.Reject -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TandemCallAction.Silence -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TandemCallAction.Hangup -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TandemCallAction.RejectWithMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is TandemCallAction.MoveToThisDevice -> (4UL)
        is TandemCallAction.MoveBack -> (4UL)
        is TandemCallAction.MuteMic -> (4UL)
    }

    override fun write(value: TandemCallAction, buf: ByteBuffer) {
        when(value) {
            is TandemCallAction.Answer -> {
                buf.putInt(1)
                Unit
            }
            is TandemCallAction.Reject -> {
                buf.putInt(2)
                Unit
            }
            is TandemCallAction.Silence -> {
                buf.putInt(3)
                Unit
            }
            is TandemCallAction.Hangup -> {
                buf.putInt(4)
                Unit
            }
            is TandemCallAction.RejectWithMessage -> {
                buf.putInt(5)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is TandemCallAction.MoveToThisDevice -> {
                buf.putInt(6)
                Unit
            }
            is TandemCallAction.MoveBack -> {
                buf.putInt(7)
                Unit
            }
            is TandemCallAction.MuteMic -> {
                buf.putInt(8)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






