sealed class TandemException: kotlin.Exception() {
    
    class Failed(
        
        val `reason`: kotlin.String
        ) : TandemException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotConnected(
        ) : TandemException() {
        override val message
            get() = ""
    }
    
    class NotTrusted(
        ) : TandemException() {
        override val message
            get() = ""
    }
    
    class Pairing(
        
        val `reason`: kotlin.String
        ) : TandemException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The other device would not do what was asked with its files. `code` is one of: not_found, denied, disabled,
     * outside, exists, not_empty, not_dir, is_dir, too_large, unsupported, io.
     */
    class Files(
        
        val `code`: kotlin.String, 
        
        val `reason`: kotlin.String
        ) : TandemException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TandemException> {
        override fun lift(error_buf: RustBuffer.ByValue): TandemException = FfiConverterTypeTandemError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTandemError : FfiConverterRustBuffer<TandemException> {
    override fun read(buf: ByteBuffer): TandemException {
        

        return when(buf.getInt()) {
            1 -> TandemException.Failed(
                FfiConverterString.read(buf),
                )
            2 -> TandemException.NotConnected()
            3 -> TandemException.NotTrusted()
            4 -> TandemException.Pairing(
                FfiConverterString.read(buf),
                )
            5 -> TandemException.Files(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TandemException): ULong {
        return when(value) {
            is TandemException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is TandemException.NotConnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is TandemException.NotTrusted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is TandemException.Pairing -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is TandemException.Files -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: TandemException, buf: ByteBuffer) {
        when(value) {
            is TandemException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is TandemException.NotConnected -> {
                buf.putInt(2)
                Unit
            }
            is TandemException.NotTrusted -> {
                buf.putInt(3)
                Unit
            }
            is TandemException.Pairing -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is TandemException.Files -> {
                buf.putInt(5)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



