 */
public object FfiConverterTypeTandemEvent : FfiConverterRustBuffer<TandemEvent>{
    override fun read(buf: ByteBuffer): TandemEvent {
        return when(buf.getInt()) {
            1 -> TandemEvent.DevicesChanged
            2 -> TandemEvent.Connected(
                FfiConverterString.read(buf),
                )
            3 -> TandemEvent.Disconnected(
                FfiConverterString.read(buf),
                )
            4 -> TandemEvent.TailscaleNeeded(
                FfiConverterString.read(buf),
                )
            5 -> TandemEvent.Paired(
                FfiConverterString.read(buf),
                )
            6 -> TandemEvent.CircleChanged
            7 -> TandemEvent.RemovedFromCircle
            8 -> TandemEvent.Clipboard(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            9 -> TandemEvent.ShareOffered(
