    override fun write(value: TandemEvent, buf: ByteBuffer) {
        when(value) {
            is TandemEvent.DevicesChanged -> {
                buf.putInt(1)
                Unit
            }
            is TandemEvent.Connected -> {
                buf.putInt(2)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is TandemEvent.Disconnected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is TandemEvent.TailscaleNeeded -> {
                buf.putInt(4)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is TandemEvent.Paired -> {
                buf.putInt(5)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is TandemEvent.CircleChanged -> {
                buf.putInt(6)
                Unit
            }
            is TandemEvent.RemovedFromCircle -> {
                buf.putInt(7)
                Unit
            }
            is TandemEvent.Clipboard -> {
                buf.putInt(8)
                FfiConverterString.write(value.`from`, buf)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterBoolean.write(value.`isUrl`, buf)
                Unit
            }
            is TandemEvent.ShareOffered -> {
                buf.putInt(9)
                FfiConverterString.write(value.`from`, buf)
                FfiConverterULong.write(value.`offer`, buf)
                FfiConverterTypeTandemShareOrigin.write(value.`origin`, buf)
                FfiConverterSequenceTypeTandemShareItem.write(value.`items`, buf)
                Unit
            }
            is TandemEvent.ShareText -> {
                buf.putInt(10)
                FfiConverterString.write(value.`from`, buf)
                FfiConverterString.write(value.`text`, buf)
