sealed class TandemHotspot {
    
    data class Request(
        val `reason`: kotlin.String) : TandemHotspot()
        
    {
        

        companion object
    }
    
    data class State(
        val `on`: kotlin.Boolean, 
        val `ssid`: kotlin.String?, 
        val `clients`: kotlin.UByte, 
        val `dataUsed`: kotlin.ULong?, 
        val `error`: kotlin.String?) : TandemHotspot()
        
    {
        

        companion object
    }
    
    object Stop : TandemHotspot()
    
    
    /**
     * The Mac left for another network: off, unless other devices are still on the hotspot.
     */
    object Leave : TandemHotspot()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeTandemHotspot : FfiConverterRustBuffer<TandemHotspot>{
    override fun read(buf: ByteBuffer): TandemHotspot {
        return when(buf.getInt()) {
            1 -> TandemHotspot.Request(
                FfiConverterString.read(buf),
                )
            2 -> TandemHotspot.State(
                FfiConverterBoolean.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterUByte.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> TandemHotspot.Stop
            4 -> TandemHotspot.Leave
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TandemHotspot): ULong = when(value) {
        is TandemHotspot.Request -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is TandemHotspot.State -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`on`)
                + FfiConverterOptionalString.allocationSize(value.`ssid`)
                + FfiConverterUByte.allocationSize(value.`clients`)
                + FfiConverterOptionalULong.allocationSize(value.`dataUsed`)
                + FfiConverterOptionalString.allocationSize(value.`error`)
            )
        }
        is TandemHotspot.Stop -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TandemHotspot.Leave -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: TandemHotspot, buf: ByteBuffer) {
        when(value) {
            is TandemHotspot.Request -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is TandemHotspot.State -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.`on`, buf)
                FfiConverterOptionalString.write(value.`ssid`, buf)
                FfiConverterUByte.write(value.`clients`, buf)
                FfiConverterOptionalULong.write(value.`dataUsed`, buf)
                FfiConverterOptionalString.write(value.`error`, buf)
                Unit
            }
            is TandemHotspot.Stop -> {
                buf.putInt(3)
                Unit
            }
            is TandemHotspot.Leave -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





